    public static function choices(array $account,array $choices):array
    {
        $code=(string)($account['skr_code']??'');$target=self::FIXED[$code]??self::COUNTERPARTS[$code]??null;
        if($target!==null)return isset($choices[$target])?[$target=>$choices[$target]]:[];
        return $choices;
    }
    private static function flat(array $item):array
    {
        if(!isset($item['plan']))return $item;
        return ['item_id'=>$item['item_id'],'account'=>$item['fixed_account'],'method'=>'cost','skr_code'=>$item['plan']['account'],
            'cost_plan'=>$item['plan'],'valuation'=>$item['valuation'],'valuation_accounts'=>$item['valuation_accounts'],
            'valuation_side'=>$item['valuation_side']??'book']+$item['schedule'];
    }
    public static function movement(array $item,string $code):?int
    {return BalanceCostAssetSources::movement(self::flat($item),$code);}
    public static function mapping(int $year,array $accounts,?array $schedule):array
    {
        if(!$schedule)return [];
        $out=[];$counters=[];$fixed=[];
        foreach($schedule['items']??[] as $raw){
            if(($raw['method']??$raw['plan']['method']??null)!=='cost')continue;$item=self::flat($raw);
            $code=$item['skr_code'];if(!isset(self::FIXED[$code]))continue;
            $period=isset($schedule['period'])?BalancePeriod::check($schedule['period'],$year):BalancePeriod::calendar($year);
            if((!isset($schedule['period'])&&($schedule['year']??null)!==$year)||!empty($schedule['issues']))throw new DomainException('Kostenanlagenverzeichnis des Abschlussjahres prüfen.');
            $side=$item['valuation_side']??'book';if(!in_array($side,['book','tax'],true))throw new DomainException('Bewertungsseite prüfen.');
            $book=array_replace($item,$item['valuation']['book']);unset($book['valuation_side']);
            BalanceCostAssetTax::item($book,$accounts,$period);
            $key=$item['account'];$out[$key]=AssetTypes::costTarget($item['cost_plan']);$v=$item['valuation'][$side];
            foreach(AssetValuation::FIELDS as $field)if(($item[$field]??null)!==$v[$field])throw new DomainException('Originale Kostenbewertung und Anlagenverzeichnis stimmen nicht überein.');
            $fixed[$key]=($fixed[$key]??0)+$v['book_closing_cents'];$retained=[];
            foreach($item['valuation']['source']['events'] as $event){
                $type=BalanceCostAssetSources::codes($item['cost_plan']['valuation_kind'],$event['kind'],$event['permanent']??true,$item['cost_plan']['financial_profile']??null,$event['counter_code']??null,$item['cost_plan']['account']);
                $counter=$type['code'];$id=FinancialInvestment::key($counter,$item['cost_plan']['financial_profile']??null);$retained[$counter]=$id;
                if(($accounts[$id]['skr_code']??null)!==$counter||$accounts[$id]['group']!==$type['group'])throw new DomainException('Originales Bewertungsgegenkonto prüfen.');
            }
            if($retained!==($item['valuation_accounts']??[]))throw new DomainException('Bewertungsgegenkonten wurden verändert.');
            foreach($retained as $counter=>$id){$out[$id]=isset($item['cost_plan']['financial_profile'])?FinancialInvestment::counterTarget((string)$counter,$item['cost_plan']['financial_profile']):self::COUNTERPARTS[$counter];$counters[$id]=($counters[$id]??0)+(BalanceCostAssetSources::movement($item,(string)$counter)??0);}
        }
        foreach($fixed+$counters as $key=>$amount)if(($accounts[$key]['amount_cents']??null)!==$amount)throw new DomainException('Kostenbewertung und zugehörige Kontensalden abstimmen.');
        return $out;
    }
